import pathlib,json,csv,hashlib
p=pathlib.Path(__file__).parent;data=json.loads((p/'results.json').read_text());rows=data['rows'];events=[json.loads(l) for l in (p/'events.jsonl').read_text().splitlines()];assert events[-1]['type']=='cross_library_experiment_complete'
refs={}
for e in events:
 for ref in ([e['evidence']] if isinstance(e.get('evidence'),dict) else e.get('evidence',[])):refs[ref['path']]=ref
for path,ref in refs.items():assert hashlib.sha256((p/path).read_bytes()).hexdigest()==ref['sha256']
within=[r for r in rows if r['mode']=='within_cluster'];cross=[r for r in rows if r['mode']=='different_cluster'];back=[r for r in rows if r['mode']=='return_to_initial']
assert len(within)==5 and all(r['result']['recognizedSearch'] and r['matchesBaseline'] for r in within)
assert len(cross)==4 and all(not r['result']['recognizedSearch'] and r['result']['selectedMember']=='All Libraries' and r['freshControl']['recognizedSearch'] for r in cross)
assert len(back)==1 and back[0]['matchesBaseline']
with (p/'comparison.csv').open('w') as f:
 fields=['mode','library','cluster','requestedMember','observedMember','httpStatus','scopedSearchWorked','matchedBaseline','recognizedScopedRows','freshControlRows'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for r in rows:w.writerow(dict(zip(fields,[r['mode'],r['name'],r['cluster'],r['requestedMember'],r['result']['selectedMember'],r['result']['status'],r['result']['recognizedSearch'],r['matchesBaseline'],r['result']['returned'],r.get('freshControl',{}).get('returned','')])))
report=['# e-Granthalaya cross-library session reuse — 8 November 2026','','**One initial form GET successfully supported five different libraries in the same JNV2 cluster. Reusing that form/session across four other clusters did not preserve library scope.**','','All tests used Title search for **Wings of Fire**. One bootstrap GET initialized JNV Hanumangarh. Every experimental POST reused its original hidden form state and session, changed the library selector to the target’s public frozen code, and used the target cluster/library URL. No intervening form fetch or item-detail lookup occurred in the ten experimental POSTs. The row field `initialFormFetchedForThisTarget:false` describes the POST step; the first library had supplied the one explicitly recorded bootstrap GET.','','## Same-cluster switches','','| Library | Returned rows | Selected library and baseline records match |','|---|---:|---|']
for r in within:report.append(f"| {r['name']} | {r['result']['returned']} | Yes |")
report+=['','Five different libraries were searched with **six catalog requests: one GET plus five POSTs**. All five result sets and native counts matched their saved successful member-scoped searches.','','## Cross-cluster switches','','| Library | Cluster | Reused-state response | Fresh GET + POST control |','|---|---|---|---:|']
for r in cross:report.append(f"| {r['name']} | {r['cluster']} | Selected All Libraries, not requested member | {r['freshControl']['returned']} scoped rows |")
report+=['','All four cross-cluster responses were HTTP 200 but selected **All Libraries**, so they fail the requested-library scope test. Zero recognized scoped rows in the CSV means the parser rejected that scope; it is not proof that the raw page displayed zero records or that the target library had no books. Each independent fresh two-request control returned the expected scoped search. Returning to the initial JNV2 library with the original session/form still reproduced its baseline results.','','## Interpretation and limits','','The tested reuse boundary is a catalog cluster: reuse worked across five members of JNV2 but failed across the four tested cluster boundaries using this request shape. This supports testing session/form pools per cluster, rather than assuming a mandatory initial GET per library. It does not establish that this will work in all 62 clusters, that state can be held indefinitely, that one session can be used concurrently, or that no alternative cross-cluster workflow exists. No production or main-audit connector code, qualification criteria or library publication status changed. Diagnostic checks do not increase newly audited ID counts.','','The main collector cooperatively checkpointed before testing and resumes unchanged after publication. Existing exclusive locks, serial pacing, policy/refusal controls and bounded HTML capture were used. Total catalog requests: 19 (one bootstrap GET, ten reuse POSTs, four fresh GET+POST controls), plus one policy request.','','## Evidence','','`comparison.csv` is the short table. `results.json` contains requested/observed scope, native IDs/titles/counts, source-dated baseline references and current controls. `events.jsonl` and `bodies/` preserve sanitized HTTP evidence; `selection.json` contains baseline provenance whose relative paths resolve under `../../india-20261108/`. Hash validation is in `validation.json`. The executed one-off harness is `test.mjs`; its workspace paths are retained. No reusable cookies or hidden form state are published.']
(p/'REPORT.md').write_text('\n'.join(report)+'\n')
(p/'validation.json').write_text(json.dumps({'valid':True,'sameClusterPasses':5,'differentClusterScopedPasses':0,'differentClusterControlsPassed':4,'returnToInitialPassed':True,'validatedBodyFiles':len(refs),'requests':sum(e['type']=='request_started' for e in events),'fileHashes':{f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in p.iterdir() if f.is_file() and f.name!='validation.json'}},indent=2)+'\n')
print((p/'comparison.csv').read_text());print('Validated',len(refs),'bodies')
